def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    start_r, start_c = start
    goal_r, goal_c = goal

    if not (is_valid(start_r, start_c) and is_valid(goal_r, goal_c)):
        return []

    if grid[start_r][start_c] == '#' or grid[goal_r][goal_c] == '#':
        return []

    if start == goal:
        return [start]

    stack = [(start, [start])]
    visited = {start}

    while stack:
        (current, path) = stack.pop()
        r, c = current

        if current == goal:
            return path

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            next_pos = (nr, nc)
            if is_valid(nr, nc) and grid[nr][nc] == '.' and next_pos not in visited:
                visited.add(next_pos)
                new_path = path + [next_pos]
                stack.append((next_pos, new_path))

    return []

