        return []
    if start == goal:
        return [start]

    stack = [start]
    visited = {start}
    predecessor = {}

    found = False
    while stack:
        current = stack.pop()
        r, c = current
        if current == goal:
            found = True
            break
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                predecessor[(nr, nc)] = current
                stack.append((nr, nc))

    if not found:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = predecessor[current]
    path.append(start)
    path.reverse()
    return path

